  const actionBaseline=useRef<{name:string;version:number}>({name:'',version:0})
  const [,setActionBaselineEpoch]=useState(0)
  const actionContext=JSON.stringify([app.version,canManage,actions]),actionContextRef=useRef(actionContext),actionContextGeneration=useRef(0)
  if(actionContextRef.current!==actionContext){actionContextRef.current=actionContext;actionContextGeneration.current++}
  const [plan,setPlan]=useState('[]'),[migrationId,setMigrationId]=useState(''),[confirmMigration,setConfirmMigration]=useState(false)
  const [migrationPreview,setMigrationPreview]=useState<MigrationPreview|null>(null)
  const [previewedPlan,setPreviewedPlan]=useState(''),[previewedMigrationId,setPreviewedMigrationId]=useState('')
  const [method,setMethod]=useState('GET'),[requestBody,setRequestBody]=useState('{}'),[confirmExternal,setConfirmExternal]=useState(false)
  const [connectionName,setConnectionName]=useState(''),[endpoint,setEndpoint]=useState(''),[token,setToken]=useState(''),[response,setResponse]=useState<unknown>(undefined)
  const [connectionAuthMode,setConnectionAuthMode]=useState<'bearer'|'oauth'>('bearer'),[oauthClientId,setOAuthClientId]=useState(''),[oauthClientSecret,setOAuthClientSecret]=useState(''),[oauthScope,setOAuthScope]=useState('openid email profile https://www.googleapis.com/auth/drive.readonly')
  const [mergeReview,setMergeReview]=useState<MergeReview|null>(null)
  const [mergeResolutions,setMergeResolutions]=useState<Record<string,'preview'|'production'>>({})
  const [mergeReviewReady,setMergeReviewReady]=useState(false)
  const [confirmLegacyRebase,setConfirmLegacyRebase]=useState(false)
  const [hosting,setHosting]=useState<AppHosting|null>(null),[hostname,setHostname]=useState(''),[publicConfirmed,setPublicConfirmed]=useState(false),[envName,setEnvName]=useState(''),[envValue,setEnvValue]=useState('')
  const [entity,setEntity]=useState('primary'),[record,setRecord]=useState('{}')
  const [forkSchemaOperations,setForkSchemaOperations]=useState('[]')
  const [forkColumnEntity,setForkColumnEntity]=useState('primary'),[forkColumnName,setForkColumnName]=useState(''),[forkColumnType,setForkColumnType]=useState('text'),[forkColumnOptions,setForkColumnOptions]=useState(''),[forkRelationTarget,setForkRelationTarget]=useState('primary'),[forkRelationMultiple,setForkRelationMultiple]=useState(false)
  const [newEntityName,setNewEntityName]=useState(''),[newEntityKey,setNewEntityKey]=useState(''),[relationSource,setRelationSource]=useState('primary'),[relationName,setRelationName]=useState(''),[relationTarget,setRelationTarget]=useState(''),[relationMultiple,setRelationMultiple]=useState(false)
  const [columnEntity,setColumnEntity]=useState('primary'),[newColumnName,setNewColumnName]=useState(''),[newColumnType,setNewColumnType]=useState('text'),[newColumnOptions,setNewColumnOptions]=useState('')
  const [manageColumnEntity,setManageColumnEntity]=useState('primary'),[manageColumnId,setManageColumnId]=useState(''),[manageColumnAction,setManageColumnAction]=useState('rename'),[renameColumnName,setRenameColumnName]=useState(''),[convertColumnType,setConvertColumnType]=useState('text'),[convertColumnOptions,setConvertColumnOptions]=useState(''),[convertRelationTarget,setConvertRelationTarget]=useState(''),[convertRelationMultiple,setConvertRelationMultiple]=useState(false)
  async function load() { setMergeReview(null);setMergeResolutions({});setMergeReviewReady(false);setMigrationPreview(null);setConfirmMigration(false); const [a,c,d,g]=await Promise.all([api.appActions(app.id),api.appConnections(app.id),api.appDatabase(app.id),api.gateways()]);if(activeScope.current!==scope)return;setActions(a.actions);setConnections(c.connections);setRemoteMcpTools(c.remoteMcp?.tools||[]);setDb(d);setNodes(g.gateways.filter(n=>!n.revokedAt)); }
  async function loadHosting() { const data=await api.appHosting(app.id);if(activeScope.current===scope)setHosting(data) }
  async function run(fn:()=>Promise<unknown>) {const operation={};activeOperations.current.add(operation);setBusy(true);setError('');setNotice('');try{await fn()}catch(e){if(activeScope.current===scope)setError(e instanceof Error?e.message:String(e))}finally{activeOperations.current.delete(operation);if(activeScope.current===scope)setBusy(activeOperations.current.size>0)}}
  useLayoutEffect(()=>{activeScope.current=scope;setHistory([]);historyRequest.current++;setHistorySelectionEpoch(value=>value+1);setActionCandidate(null);setActionRuns(null);setActionRunsCursor(undefined);setActionRunResults({});setActionRunsLoading(false);setActionRunLoadingId(null);actionEditGeneration.current++;actionBaseline.current={name:'',version:0};activeOperations.current.clear();actionGenerationPending.current=null;setBusy(false);setHosting(null);setHostname('');setPublicConfirmed(false);setEnvName('');setEnvValue('');return()=>{if(activeScope.current===scope)activeScope.current=null}},[scope])
  useEffect(()=>{void run(load)},[app.id,api])
  const selected=actions.find(a=>a.name===name),conn=connections.find(c=>c.name===connectionName)
  const selectAction=(a:AppAction)=>{actionEditGeneration.current++;historyRequest.current++;setHistorySelectionEpoch(value=>value+1);actionBaseline.current={name:a.name,version:a.version};setHistory([]);setName(a.name);setCode(a.draft||a.published||'');setLanguage(a.language||'javascript')}
  async function loadActionRuns(cursor?:string,replace=false) {
    if(!api.actionRunHistory)return
    setActionRunsLoading(true)
    try { await run(async()=>{const page=await api.actionRunHistory(app.id,cursor);if(activeScope.current!==scope)return;setActionRuns(previous=>replace||!previous?page.runs:[...previous,...page.runs]);setActionRunsCursor(page.nextCursor)}) }
    finally {if(activeScope.current===scope)setActionRunsLoading(false)}
  }
  // Keep visible executions current without asking the user to refresh. Poll
  // only jobs the current user opened (and the one they just started); the
  // server rechecks the creator and current App access on every read.
  useEffect(()=>{
    if(!job||!['queued','running'].includes(job.status))return
    let stopped=false,inFlight=false
    const poll=async()=>{
      if(stopped||inFlight)return
      inFlight=true
      try{const response=await api.actionJob(app.id,job.id);if(!stopped&&activeScope.current===scope)setJob(response.job)}catch{/* Keep retrying while the run is active. */}finally{inFlight=false}
    }
    const timer=setInterval(()=>void poll(),2000)
    return()=>{stopped=true;clearInterval(timer)}
  },[job?.id,job?.status,api,app.id,scope])
  useEffect(()=>{
    const active=Object.entries(actionRunResults).filter(([,result])=>['queued','running'].includes(result.status)).map(([id])=>id)
    if(!active.length)return
    let stopped=false,inFlight=false
    const poll=async()=>{
      if(stopped||inFlight)return
      inFlight=true
      try{
        const updates=await Promise.all(active.slice(0,10).map(async id=>{try{return [id,(await api.actionJob(app.id,id)).job] as const}catch{return null}}))
        if(!stopped&&activeScope.current===scope)setActionRunResults(previous=>{const next={...previous};for(const item of updates)if(item)next[item[0]]=item[1];return next})
      }finally{inFlight=false}
    }
    const timer=setInterval(()=>void poll(),2000)
    return()=>{stopped=true;clearInterval(timer)}
  },[actionRunResults,api,app.id,scope])
  const advanceActionBaseline=(target:string,expected:number,saved:{version?:number})=>{if(!Number.isSafeInteger(expected)||!Number.isSafeInteger(saved.version)||saved.version!==expected+1)throw new Error(t('Could not verify the saved action version. Keep your current input and reload before continuing.'));if(actionBaseline.current.name===target&&actionBaseline.current.version===expected)actionBaseline.current={name:target,version:saved.version!}}
